CREATE TABLE IF NOT EXISTS products ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, price TEXT NOT NULL, priceKRW INTEGER, year TEXT, mileage TEXT, fuel TEXT, description TEXT, categoryId INTEGER, status TEXT DEFAULT 'active', images TEXT, options TEXT, isFeatured BOOLEAN DEFAULT 0, engine TEXT, transmission TEXT, drive TEXT, color TEXT, interiorColor TEXT, doors TEXT, created_at INTEGER DEFAULT (strftime('%s', 'now')) );
CREATE TABLE IF NOT EXISTS categories ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, icon TEXT, image TEXT, count INTEGER DEFAULT 0, sort_order INTEGER DEFAULT 0 );
CREATE TABLE IF NOT EXISTS banners ( id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, subtitle TEXT, image TEXT, bg TEXT, active BOOLEAN DEFAULT 1 );
CREATE TABLE IF NOT EXISTS users ( id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, name TEXT, phone TEXT, avatar TEXT, created_at INTEGER DEFAULT (strftime('%s', 'now')) );
CREATE TABLE IF NOT EXISTS reservations ( id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL, product_name TEXT NOT NULL, user_id TEXT, user_name TEXT NOT NULL, phone TEXT NOT NULL, facebook_id TEXT, status TEXT DEFAULT 'pending', created_at INTEGER DEFAULT (strftime('%s', 'now')), status_updated_at INTEGER, FOREIGN KEY (product_id) REFERENCES products(id) );
CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at INTEGER DEFAULT (strftime('%s', 'now')) );
INSERT OR IGNORE INTO settings (key, value) VALUES ('exchange_rate', '2.5');
CREATE TABLE IF NOT EXISTS reviews ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, user_name TEXT NOT NULL, car_model TEXT, comment TEXT NOT NULL, rating INTEGER DEFAULT 5, gender TEXT DEFAULT 'male', created_at INTEGER DEFAULT (strftime('%s', 'now')) );
